--
-- Name: audit_capture(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_capture() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  pk_cols text[];
  old_json jsonb;
  new_json jsonb;
  pk_json jsonb;
  changed_cols text[];
  actor_id uuid;
BEGIN
  IF (TG_OP = 'DELETE') THEN
    old_json := to_jsonb(OLD);
  ELSIF (TG_OP = 'INSERT') THEN
    new_json := to_jsonb(NEW);
  ELSE
    old_json := to_jsonb(OLD);
    new_json := to_jsonb(NEW);
    SELECT array_agg(e.key ORDER BY e.key) INTO changed_cols
    FROM jsonb_each(new_json) AS e
    WHERE old_json -> e.key IS DISTINCT FROM new_json -> e.key;
  END IF;

  SELECT array_agg(a.attname ORDER BY a.attnum) INTO pk_cols
  FROM pg_index i
  JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = ANY (i.indkey)
  WHERE i.indrelid = TG_RELID AND i.indisprimary;

  IF pk_cols IS NOT NULL THEN
    IF (TG_OP = 'DELETE') THEN
      SELECT jsonb_object_agg(k, old_json -> k) INTO pk_json FROM unnest(pk_cols) AS k;
    ELSE
      SELECT jsonb_object_agg(k, new_json -> k) INTO pk_json FROM unnest(pk_cols) AS k;
    END IF;
  END IF;

  -- Không để lỗi ép kiểu actor làm hỏng giao dịch nghiệp vụ.
  BEGIN
    actor_id := NULLIF(current_setting('app.actor_staff_id', true), '')::uuid;
  EXCEPTION WHEN others THEN
    actor_id := NULL;
  END;

    table_name, operation, row_pk, old_data, new_data, changed_columns,
    actor_staff_id, actor_email, request_id, ip, user_agent, changed_at
  ) VALUES (
    TG_TABLE_NAME, TG_OP, pk_json::text, audit_redact_credentials(old_json), audit_redact_credentials(new_json), changed_cols,
    actor_id,
    NULLIF(current_setting('app.actor_email', true), ''),
    NULLIF(current_setting('app.request_id', true), ''),
    NULLIF(current_setting('app.ip', true), ''),
    NULLIF(current_setting('app.user_agent', true), ''),
    now()
  );

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: audit_redact_credentials(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_redact_credentials(payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE result jsonb; item record;
BEGIN
  IF jsonb_typeof(payload) = 'object' THEN
    result := '{}'::jsonb;
    FOR item IN SELECT key, value FROM jsonb_each(payload) LOOP
      result := result || jsonb_build_object(item.key,
        CASE WHEN regexp_replace(lower(item.key), '[^a-z0-9]', '', 'g') = ANY (ARRAY[
          'password', 'passwordhash', 'passwordresettoken', 'resettoken',
          'refreshtoken', 'accesstoken', 'apikey', 'secret', 'clientsecret',
          'sessionsecret', 'privatekey', 'totpsecret', 'mfasecret', 'recoverycodes', 'backupcodes'
        ]) THEN to_jsonb('[REDACTED]'::text)
        ELSE audit_redact_credentials(item.value) END);
    END LOOP;
    RETURN result;
  ELSIF jsonb_typeof(payload) = 'array' THEN
    SELECT COALESCE(jsonb_agg(audit_redact_credentials(value) ORDER BY ord), '[]'::jsonb)
      INTO result FROM jsonb_array_elements(payload) WITH ORDINALITY AS e(value, ord);
    RETURN result;
  END IF;
  RETURN payload;
END;
$$;


--
-- Name: freeze_rosters_before_membership_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.freeze_rosters_before_membership_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
      DECLARE linked record;
      BEGIN
        PERFORM pg_advisory_xact_lock(21026);
        FOR linked IN SELECT DISTINCT course_offering_id FROM course_offering_class_groups
          WHERE class_group_id = CASE WHEN TG_OP = 'DELETE' THEN OLD.class_group_id ELSE NEW.class_group_id END
            OR (TG_OP = 'UPDATE' AND class_group_id = OLD.class_group_id)
        LOOP PERFORM freeze_started_offering_roster(linked.course_offering_id); END LOOP;
        IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
        RETURN NEW;
      END $$;


--
-- Name: freeze_rosters_before_timetable_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.freeze_rosters_before_timetable_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
      BEGIN
        PERFORM pg_advisory_xact_lock(21026);
        IF TG_OP <> 'INSERT' THEN
          PERFORM freeze_started_offering_roster(OLD.course_offering_id,
            (OLD.session_date + OLD.start_time) AT TIME ZONE 'Asia/Ho_Chi_Minh');
        END IF;
        IF TG_OP <> 'DELETE' THEN
          PERFORM freeze_started_offering_roster(NEW.course_offering_id,
            (NEW.session_date + NEW.start_time) AT TIME ZONE 'Asia/Ho_Chi_Minh');
          RETURN NEW;
        END IF;
        RETURN OLD;
      END $$;


--
-- Name: freeze_started_offering_roster(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.freeze_started_offering_roster(offering_id uuid, previous_start timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    AS $$
      DECLARE cutoff timestamptz;
      BEGIN
        SELECT roster_started_at INTO cutoff FROM course_offerings WHERE id = offering_id;
        IF cutoff IS NULL THEN
        SELECT MIN(moment) INTO cutoff FROM (
          SELECT (session_date + start_time) AT TIME ZONE 'Asia/Ho_Chi_Minh' AS moment
          FROM teaching_sessions WHERE course_offering_id = offering_id
          UNION ALL
          SELECT completed_at FROM course_offerings WHERE id = offering_id AND status = 'completed'
          UNION ALL SELECT previous_start
        ) boundaries WHERE moment <= clock_timestamp();
        END IF;
        IF cutoff IS NULL THEN RETURN; END IF;
        UPDATE course_offerings SET roster_started_at = cutoff WHERE id = offering_id AND roster_started_at IS NULL;
        UPDATE course_offering_class_groups link SET participant_ids = ARRAY(
          SELECT DISTINCT participant_id FROM (
            SELECT CASE WHEN COALESCE(member.student_id, record.student_id) IS NOT NULL
              THEN 'student:' || COALESCE(member.student_id, record.student_id)::text
              WHEN member.admission_record_id IS NOT NULL THEN 'admission:' || member.admission_record_id::text END AS participant_id
            FROM academic_class_members member
            LEFT JOIN admission_records record ON record.id = member.admission_record_id
            WHERE member.class_group_id = link.class_group_id AND member.enrolled_at <= cutoff
              AND (member.left_at IS NULL OR member.left_at >= (SELECT created_at FROM course_offerings WHERE id = offering_id))
            UNION ALL
            -- Preserve recorded results when historical enrollment timestamps
            -- were imported after the actual teaching dates.
            SELECT grade->>'participantId' FROM course_exam_gradebooks book
            CROSS JOIN LATERAL jsonb_array_elements(book.grades) grade
            WHERE book.course_offering_id = offering_id AND book.class_group_id = link.class_group_id
          ) people WHERE participant_id IS NOT NULL ORDER BY participant_id
        ), updated_at = clock_timestamp()
        WHERE link.course_offering_id = offering_id AND link.participant_ids IS NULL;
      END $$;


