--
-- Name: academic_class_members; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.academic_class_members AS
 SELECT class_group_members.id,
    class_group_members.class_group_id,
    class_group_members.admission_record_id,
    class_group_members.student_id,
    class_group_members.enrolled_at,
    NULL::timestamp with time zone AS left_at
   FROM public.class_group_members
UNION ALL
 SELECT class_membership_history.id,
    class_membership_history.class_group_id,
    class_membership_history.admission_record_id,
    class_membership_history.student_id,
    class_membership_history.enrolled_at,
    class_membership_history.left_at
   FROM public.class_membership_history;


