--
-- Name: course_exam_sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.course_exam_sessions (
    id uuid NOT NULL,
    course_offering_id uuid NOT NULL,
    eligibility_snapshot_id uuid NOT NULL,
    exam_date date NOT NULL,
    start_time time without time zone NOT NULL,
    end_time time without time zone NOT NULL,
    room_id uuid NOT NULL,
    status text DEFAULT 'scheduled'::text NOT NULL,
    version integer DEFAULT 0 NOT NULL,
    created_by uuid NOT NULL,
    updated_by uuid NOT NULL,
    confirmed_by uuid,
    confirmed_at timestamp with time zone,
    note text DEFAULT ''::text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    lecturer_id uuid,
    arrangement_id uuid NOT NULL,
    round_no integer DEFAULT 1 NOT NULL,
    external_invigilator_name character varying(255),
    external_unit_name character varying(255),
    external_invigilator_key text,
    CONSTRAINT course_exam_external_invigilator_consistent CHECK ((((external_invigilator_name IS NULL) AND (external_unit_name IS NULL) AND (external_invigilator_key IS NULL)) OR ((lecturer_id IS NULL) AND (external_invigilator_name IS NOT NULL) AND (length(btrim((external_invigilator_name)::text)) > 0) AND (external_unit_name IS NOT NULL) AND (length(btrim((external_unit_name)::text)) > 0) AND (external_invigilator_key IS NOT NULL)))),
    CONSTRAINT course_exam_sessions_check CHECK ((end_time > start_time)),
    CONSTRAINT course_exam_sessions_check1 CHECK (((status = ANY (ARRAY['held'::text, 'not_held'::text])) = ((confirmed_by IS NOT NULL) AND (confirmed_at IS NOT NULL)))),
    CONSTRAINT course_exam_sessions_round_no_check CHECK ((round_no > 0)),
    CONSTRAINT course_exam_sessions_status_check CHECK ((status = ANY (ARRAY['scheduled'::text, 'held'::text, 'not_held'::text, 'cancelled'::text]))),
    CONSTRAINT course_exam_sessions_version_check CHECK ((version >= 0))
);


--
-- Name: course_exam_workflows; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.course_exam_workflows (
    course_offering_id uuid NOT NULL,
    mode text DEFAULT 'new'::text NOT NULL,
    eligibility_status text DEFAULT 'draft'::text NOT NULL,
    eligibility_version integer DEFAULT 0 NOT NULL,
    eligibility_submission jsonb,
    eligibility_snapshot_id uuid,
    result_status text DEFAULT 'not_available'::text NOT NULL,
    result_version integer DEFAULT 0 NOT NULL,
    result_snapshot jsonb,
    legacy_evidence jsonb,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT course_exam_workflows_check CHECK (((eligibility_status <> 'approved'::text) OR (eligibility_snapshot_id IS NOT NULL))),
    CONSTRAINT course_exam_workflows_eligibility_status_check CHECK ((eligibility_status = ANY (ARRAY['draft'::text, 'submitted'::text, 'approved'::text]))),
    CONSTRAINT course_exam_workflows_eligibility_version_check CHECK ((eligibility_version >= 0)),
    CONSTRAINT course_exam_workflows_mode_check CHECK ((mode = ANY (ARRAY['new'::text, 'legacy_preserved'::text]))),
    CONSTRAINT course_exam_workflows_result_status_check CHECK ((result_status = ANY (ARRAY['not_available'::text, 'draft'::text, 'submitted'::text, 'approved'::text]))),
    CONSTRAINT course_exam_workflows_result_version_check CHECK ((result_version >= 0))
);


