    completed_at timestamp with time zone,
    completed_by_staff_id uuid,
    note text,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    participant_notes jsonb DEFAULT '[]'::jsonb NOT NULL,
    retake_weekdays integer[] DEFAULT ARRAY[1, 2, 3, 4, 5, 6, 0] NOT NULL,
    name character varying(255),
    gradebook_status character varying(20) DEFAULT 'draft'::character varying NOT NULL,
    gradebook_version integer DEFAULT 0 NOT NULL,
    gradebook_snapshot jsonb,
    roster_started_at timestamp with time zone,
    CONSTRAINT course_offerings_completion_state_check CHECK ((((status = 'active'::public.enum_course_offerings_status) AND (completed_at IS NULL) AND (completed_by_staff_id IS NULL)) OR ((status = 'completed'::public.enum_course_offerings_status) AND (completed_at IS NOT NULL) AND (completed_by_staff_id IS NOT NULL)))),
    CONSTRAINT course_offerings_gradebook_status_check CHECK (((gradebook_status)::text = ANY ((ARRAY['draft'::character varying, 'submitted'::character varying, 'approved'::character varying])::text[])))
);


