);


--
-- Name: students; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.students (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name_with_initials character varying(255) NOT NULL,
    full_name character varying(255) NOT NULL,
    postal_address text NOT NULL,
    email character varying(255) NOT NULL,
    tel_no character varying(255) NOT NULL,
    password character varying(255) NOT NULL,
    role public.enum_students_role DEFAULT 'student'::public.enum_students_role NOT NULL,
    account_type public.enum_students_account_type NOT NULL,
    approval_state public.enum_students_approval_state DEFAULT 'not approved'::public.enum_students_approval_state NOT NULL,
    registered_date timestamp with time zone,
    reg_no character varying(255) DEFAULT 'Not Set'::character varying NOT NULL,
    date_of_registration timestamp with time zone,
    degree public.enum_students_degree,
    study_mode public.enum_students_study_mode DEFAULT 'Not Set'::public.enum_students_study_mode NOT NULL,
    research_area text,
    research_program character varying(255),
    completion_year integer,
    progress_level public.enum_students_progress_level,
    date_of_last_submission timestamp with time zone,
    website_url text,
    password_reset_token character varying(255),
    password_reset_expires timestamp with time zone,
    photo character varying(255),
    document_path character varying(255),
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT students_completion_year_range CHECK (((completion_year IS NULL) OR ((completion_year >= 1900) AND (completion_year <= 2200)))),
    CONSTRAINT students_email_lowercase CHECK (((email)::text = lower((email)::text))),
    CONSTRAINT students_research_program_values CHECK (((research_program IS NULL) OR ((research_program)::text = ANY ((ARRAY['phd'::character varying, 'mphill'::character varying])::text[]))))
);


--
-- Name: study_leaves; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.study_leaves (
    id uuid NOT NULL,
    admission_record_id uuid NOT NULL,
    reason text NOT NULL,
    start_date date NOT NULL,
    end_date date NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    activated_at timestamp with time zone,
    closed_date date,
    decision_note text,
    extensions jsonb DEFAULT '[]'::jsonb NOT NULL,
    history jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT study_leaves_check CHECK ((end_date >= start_date)),
    CONSTRAINT study_leaves_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'resumed'::text, 'withdrawn'::text])))
);


