    learning_result_id uuid,
    source_subject_id uuid NOT NULL,
    target_subject_id uuid NOT NULL,
    source_course_offering_id uuid,
    status character varying(20) DEFAULT 'approved'::character varying NOT NULL,
    basis character varying(30) DEFAULT 'canonical_subject'::character varying NOT NULL,
    source_type character varying(30) DEFAULT 'regular'::character varying NOT NULL,
    decision_no character varying(100),
    decided_at timestamp with time zone,
    note text,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL
);


--
-- Name: subjects; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.subjects (
    id uuid NOT NULL,
    code character varying(20) NOT NULL,
    name character varying(200) NOT NULL,
    major_id uuid NOT NULL,
    credits integer DEFAULT 3 NOT NULL,
    sort_order integer DEFAULT 0,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    code_number integer DEFAULT 0 NOT NULL,
    code_text character varying(20) DEFAULT ''::character varying NOT NULL,
    major_assignment boolean DEFAULT false NOT NULL,
    subject_type character varying(10) DEFAULT 'CN'::character varying NOT NULL,
    is_required boolean DEFAULT true NOT NULL,
    program public.enum_subjects_program DEFAULT 'masters'::public.enum_subjects_program NOT NULL,
    canonical_subject_id uuid,
    allow_cross_major boolean DEFAULT false NOT NULL,
    shared_major_ids uuid[] DEFAULT ARRAY[]::uuid[] NOT NULL,
    CONSTRAINT subjects_alias_not_cross_major_root_check CHECK (((canonical_subject_id IS NULL) OR (allow_cross_major = false))),
    CONSTRAINT subjects_canonical_not_self_check CHECK (((canonical_subject_id IS NULL) OR (canonical_subject_id <> id)))
);


--
-- Name: submissions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.submissions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    student_id uuid NOT NULL,
    submission_number smallint NOT NULL,
    file_name character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT submissions_number_range CHECK (((submission_number >= 1) AND (submission_number <= 7)))
);


--
-- Name: teaching_sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.teaching_sessions (
    id uuid NOT NULL,
    course_offering_id uuid NOT NULL,
    session_date date NOT NULL,
    start_time time without time zone NOT NULL,
    end_time time without time zone NOT NULL,
    lecturer_id uuid NOT NULL,
    room_id uuid NOT NULL,
    note text,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    period public.enum_teaching_sessions_period NOT NULL,
    status public.enum_teaching_sessions_status DEFAULT 'planned'::public.enum_teaching_sessions_status NOT NULL,
    confirmed_at timestamp with time zone,
    confirmed_by_staff_id uuid,
    CONSTRAINT teaching_sessions_confirmation_state_check CHECK ((((status = 'planned'::public.enum_teaching_sessions_status) AND (confirmed_at IS NULL) AND (confirmed_by_staff_id IS NULL)) OR ((status = ANY (ARRAY['held'::public.enum_teaching_sessions_status, 'not_held'::public.enum_teaching_sessions_status])) AND (confirmed_at IS NOT NULL) AND (confirmed_by_staff_id IS NOT NULL)))),
    CONSTRAINT teaching_sessions_time_range_check CHECK ((start_time < end_time))
);


