--
-- Name: v_class_lists; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_class_lists AS
 SELECT cg.id AS class_group_id,
    cg.program,
    cg.code AS class_code,
    cg.name AS class_name,
    cg.academic_year,
    cg.status AS class_status,
    m.name AS major_name,
    cgm.id AS member_id,
    s.id AS student_id,
    s.full_name,
    s.reg_no,
    s.email,
    s.study_mode
   FROM (((public.class_groups cg
     LEFT JOIN public.majors m ON ((m.id = cg.major_id)))
     LEFT JOIN public.class_group_members cgm ON ((cgm.class_group_id = cg.id)))
     LEFT JOIN public.students s ON ((s.id = cgm.student_id)));


--
-- Name: v_graduation_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_graduation_summary AS
 SELECT s.id AS student_id,
    s.full_name,
    s.reg_no,
    s.email,
    s.degree,
    gd.id AS defense_id,
    gd.thesis_title,
    gd.defense_date,
    gd.result AS defense_result,
    gr.status AS record_status,
    gr.submitted_at,
    gr.approved_at
   FROM ((public.students s
     LEFT JOIN public.graduation_defenses gd ON ((gd.student_id = s.id)))
     LEFT JOIN public.graduation_records gr ON ((gr.student_id = s.id)));


--
-- Name: v_temp_score_doctoral; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_temp_score_doctoral AS
 SELECT es.id AS session_id,
    es.code AS session_code,
    es.name AS session_name,
    cg.id AS class_group_id,
    cg.name AS class_name,
    s.id AS student_id,
    s.full_name,
    s.reg_no,
    er.score,
    er.grade,
    er.result,
    er.created_at AS recorded_at
   FROM (((public.exam_sessions es
     LEFT JOIN public.class_groups cg ON ((cg.id = es.class_group_id)))
     LEFT JOIN public.exam_results er ON ((er.session_id = es.id)))
     LEFT JOIN public.students s ON ((s.id = er.student_id)))
  WHERE (es.program = 'doctoral'::public.enum_exam_sessions_program);


--
-- Name: v_temp_score_masters; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_temp_score_masters AS
 SELECT es.id AS session_id,
    es.code AS session_code,
    es.name AS session_name,
    cg.id AS class_group_id,
    cg.name AS class_name,
    s.id AS student_id,
    s.full_name,
    s.reg_no,
    er.score,
    er.grade,
    er.result,
    er.created_at AS recorded_at
   FROM (((public.exam_sessions es
     LEFT JOIN public.class_groups cg ON ((cg.id = es.class_group_id)))
     LEFT JOIN public.exam_results er ON ((er.session_id = es.id)))
     LEFT JOIN public.students s ON ((s.id = er.student_id)))
  WHERE (es.program = 'masters'::public.enum_exam_sessions_program);


